let patched = 0
for (const patch of PATCHES) {
  const file = fileURLToPath(new URL(patch.file, import.meta.url))
  if (!existsSync(file)) {
    console.log('[patch-dsh] ' + patch.file + ' not found — skipping')
    continue
  }
  const source = readFileSync(file, 'utf8')
  // "Already carries the fix" is decided by the fixed text itself: the entry
  // applies only while the original block is present and the fixed block is not.
  if (source.includes(patch.fixed)) {
    console.log('[patch-dsh] ' + patch.file + ' already carries the fix — no-op')
    continue
  }
  if (!source.includes(patch.original)) {
    console.error('[patch-dsh] ERROR: ' + patch.file + ' does not match the expected upstream content; cannot apply the patch.')
    console.error('If @deepseek-ai/dsh was upgraded, check whether the fixes landed upstream, then remove this script and the package.json postinstall entry.')
    process.exit(1)
  }
  writeFileSync(file, source.replace(patch.original, patch.fixed))
  console.log('[patch-dsh] patched ' + patch.file)
  patched += 1
}
console.log('[patch-dsh] ' + patched + ' patch(es) applied')
